package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarArchiveOutputStream#finish()
 */
public class TarArchiveOutputStream_finish_TriageGen2Test {

    @Test
    public void testFinishWritesTwoEOFRecords() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            // Add an entry to ensure the stream is in a valid state for finishing
            TarArchiveEntry entry = new TarArchiveEntry("test.txt");
            taos.putArchiveEntry(entry);
            taos.write("hello".getBytes());
            taos.closeArchiveEntry();

            taos.finish();
        }

        byte[] result = baos.toByteArray();

        // In Tar format, an EOF record is a block of 512 zero bytes.
        // The finish() method calls writeEOFRecord() twice.
        // We check if the trailing bytes are zeroed out in blocks of 512.

        // A simple way to verify is to check if the last 1024 bytes are all zeros 
        // (representing the two EOF blocks), assuming the content before wasn't exactly that.
        // However, a more robust way is to check the length and the content.

        int eofBlockSize = 512;
        int expectedEOFBytes = eofBlockSize * 2;

        Assert.assertTrue("Result should be at least two EOF blocks long", result.length >= expectedEOFBytes);

        // Verify the last 1024 bytes are zero
        for (int i = result.length - expectedEOFBytes; i < result.length; i++) {
            Assert.assertEquals("Byte at index " + i + " should be 0 for EOF record", 0, result[i]);
        }
    }

    @Test
    public void testFinishWithEmptyArchive() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            taos.finish();
        }

        byte[] result = baos.toByteArray();

        // Even with no entries, finish() should write two EOF blocks
        Assert.assertEquals("Should contain exactly two EOF blocks", 1024, result.length);
        for (byte b : result) {
            Assert.assertEquals(0, b);
        }
    }

    @Test(expected = IOException.class)
    public void testFinishOnClosedOutputStreamThrowsException() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);
        taos.close();

        // Calling finish after close should trigger an IOException from the underlying stream
        taos.finish();
    }

    @Test
    public void testFinishFollowedByClose() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            taos.finish();
            taos.close();
        }

        byte[] result = baos.toByteArray();
        // Ensure the stream is valid and contains the EOF markers
        Assert.assertTrue(result.length >= 1024);
        for (int i = result.length - 1024; i < result.length; i++) {
            Assert.assertEquals(0, result[i]);
        }
    }
}
